-- Metadata only. Execute against the verified disposable project only.
-- No user rows, credentials, function calls into application code, or mutations.
begin isolation level repeatable read read only;
select jsonb_build_object(
  'captured_at', current_timestamp,
  'database', current_database(),
  'current_user', current_user,
  'read_only', current_setting('transaction_read_only'),
  'server_version', current_setting('server_version'),
  'disposable_marker', exists(select 1 from public.pos_release_test_marker where marker = 'disposable-pos-atomic-sales'),
  'relation', (select jsonb_build_object('oid',c.oid,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'acl',c.relacl) from pg_class c where c.oid='public.profiles'::regclass),
  'columns', (select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'acl',a.attacl) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid='public.profiles'::regclass and a.attnum>0 and not a.attisdropped),
  'table_grants', (select jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(x.grantor),'grantee',case when x.grantee=0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end,'privilege',x.privilege_type,'grantable',x.is_grantable)) from pg_class c cross join lateral aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x where c.oid='public.profiles'::regclass),
  'column_grants', (select coalesce(jsonb_agg(jsonb_build_object('column',a.attname,'grantor',pg_get_userbyid(x.grantor),'grantee',case when x.grantee=0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end,'privilege',x.privilege_type,'grantable',x.is_grantable)), '[]'::jsonb) from pg_attribute a cross join lateral aclexplode(a.attacl) x where a.attrelid='public.profiles'::regclass and a.attnum>0 and not a.attisdropped),
  'policies', (select coalesce(jsonb_agg(jsonb_build_object('name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,'roles',(select jsonb_agg(case when r=0 then 'PUBLIC' else pg_get_userbyid(r) end) from unnest(p.polroles) r),'using',pg_get_expr(p.polqual,p.polrelid),'with_check',pg_get_expr(p.polwithcheck,p.polrelid))), '[]'::jsonb) from pg_policy p where p.polrelid='public.profiles'::regclass),
  'roles', (select jsonb_agg(jsonb_build_object('name',rolname,'superuser',rolsuper,'inherit',rolinherit,'bypass_rls',rolbypassrls,'can_login',rolcanlogin)) from pg_roles),
  'memberships', (select coalesce(jsonb_agg(to_jsonb(m) || jsonb_build_object('role',pg_get_userbyid(m.roleid),'member_name',pg_get_userbyid(m.member),'grantor_name',pg_get_userbyid(m.grantor))), '[]'::jsonb) from pg_auth_members m),
  'effective_role_memberships', (select jsonb_agg(jsonb_build_object('role',b.rolname,'target',r.rolname,'member',pg_has_role(b.oid,r.oid,'MEMBER'),'usage',pg_has_role(b.oid,r.oid,'USAGE'))) from pg_roles b cross join pg_roles r where b.rolname in ('anon','authenticated','service_role','authenticator') and b.oid<>r.oid and pg_has_role(b.oid,r.oid,'MEMBER')),
  'effective_table_privileges', (select jsonb_agg(jsonb_build_object('role',r.rolname,'privilege',v.p,'allowed',has_table_privilege(r.oid,'public.profiles',v.p),'schema_usage',has_schema_privilege(r.oid,'public','USAGE'),'schema_create',has_schema_privilege(r.oid,'public','CREATE'))) from pg_roles r cross join (values ('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER'),('MAINTAIN')) v(p) where r.rolname in ('anon','authenticated','service_role','authenticator')),
  'effective_column_privileges', (select jsonb_agg(jsonb_build_object('role',r.rolname,'column',a.attname,'privilege',v.p,'allowed',has_column_privilege(r.oid,a.attrelid,a.attnum,v.p))) from pg_roles r cross join pg_attribute a cross join (values ('SELECT'),('INSERT'),('UPDATE'),('REFERENCES')) v(p) where r.rolname in ('anon','authenticated','service_role') and a.attrelid='public.profiles'::regclass and a.attnum>0 and not a.attisdropped),
  'schema', (select jsonb_build_object('owner',pg_get_userbyid(n.nspowner),'acl',n.nspacl) from pg_namespace n where n.nspname='public'),
  'default_acls', (select coalesce(jsonb_agg(to_jsonb(d) || jsonb_build_object('role',pg_get_userbyid(d.defaclrole),'schema',n.nspname)), '[]'::jsonb) from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace where d.defaclnamespace=0 or n.nspname='public'),
  'functions', (select coalesce(jsonb_agg(jsonb_build_object('oid',p.oid,'schema',n.nspname,'name',p.proname,'identity_args',pg_get_function_identity_arguments(p.oid),'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'config',p.proconfig,'acl',p.proacl,'definition',pg_get_functiondef(p.oid),'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_execute',has_function_privilege('service_role',p.oid,'EXECUTE'))), '[]'::jsonb) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where p.prokind in ('f','p') and n.nspname not in ('pg_catalog','information_schema') and (p.prosrc ilike '%profiles%' or (n.nspname='public' and p.prosecdef))),
  'triggers', (select coalesce(jsonb_agg(jsonb_build_object('table',t.tgrelid::regclass::text,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid),'function_oid',t.tgfoid)), '[]'::jsonb) from pg_trigger t where not t.tgisinternal and (t.tgrelid='public.profiles'::regclass or t.tgfoid in (select p.oid from pg_proc p where p.prosrc ilike '%profiles%'))),
  'views', (select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'owner',pg_get_userbyid(c.relowner),'options',c.reloptions,'acl',c.relacl,'definition',pg_get_viewdef(c.oid,true))), '[]'::jsonb) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind in ('v','m') and n.nspname not in ('pg_catalog','information_schema') and pg_get_viewdef(c.oid,true) ilike '%profiles%'),
  'constraints', (select coalesce(jsonb_agg(jsonb_build_object('name',c.conname,'table',c.conrelid::regclass::text,'definition',pg_get_constraintdef(c.oid))), '[]'::jsonb) from pg_constraint c where c.conrelid='public.profiles'::regclass or c.confrelid='public.profiles'::regclass)
);
rollback;
